import re
from taf.ul.sc.unix_functionality import UnixFunctionality


class GenericController(UnixFunctionality):
    def __init__(self,
                 device_name='RTG1_CONSOLE',    # type: 'Optional[str]'
                 device=None,                   # type: 'Optional[RtgController]'
                 autoconnect=True,              # type: 'Optional[bool]'
                 get_device=False               # type: 'Optional[bool]'
                 ):

        super(GenericController, self).__init__(device_name=device_name, device=device,
                                                autoconnect=autoconnect, get_device=get_device)
        self.dsp_crash_obsevers = []
        self._connection_type = None
        self._host = None

    def get_controller_version(self):
        cat_cmd = self.device.get_cmd(cmd_name="cat", cmd_params={"path": "/rom/TargetBD.xml"})
        cat_cmd()
        for line in cat_cmd.current_ret["LINES"]:
            version = re.search(r"softwareReleaseVersion=\"(?P<VERSION>.*?)\"", line)
            if version:
                return version.group("VERSION")
        return None

    def restart_reset_counter(self):
        """Restart reset counter by doing cpldmem 0x100 0 on RTG/CUS Console

        :return: None
        """
        cmd = self.device.get_cmd(cmd_name="cpldmem", cmd_params={"address": "0x100", "value": 0})
        cmd()

    def start_dsp_crash_observer(self):
        """Start all observers for events related to DSP crash.

        :return: None
        """
        time_shift = self.device.get_event(event_name="time_shift_detected", event_params={"till_occurs_times": 1})
        ccs_crashed = self.device.get_event(event_name="ccs_crashed", event_params={"till_occurs_times": 1})
        ccs_assertion_failed = self.device.get_event(event_name="ccs_assertion_failed",
                                                     event_params={"till_occurs_times": 1})
        self.dsp_crash_obsevers = [time_shift, ccs_crashed, ccs_assertion_failed]
        for observer in self.dsp_crash_obsevers:
            observer.start()

    def cancel_dsp_crash_observer(self):
        """Cancel all observers for events related to DSP crash.

        :return: None
        """
        for observer in self.dsp_crash_obsevers:
            observer.cancel()
        self.dsp_crash_obsevers = []

    @property
    def connection_type(self):
        if self._connection_type is None:
            self._connection_type = self.get_connection_type()
        return self._connection_type

    def get_connection_type(self):
        """Return type of connection to controller.

        :return: Connection type.
        """
        try:
            connection_type = self.device.get_configurations("PROXY_PC", "LINUX")['execute_command']
        except KeyError:
            connection_type = self.device.get_configurations("UNIX_LOCAL", "LINUX")['execute_command']
        return connection_type

    @property
    def host(self):
        if self._host is None:
            self._host = self.get_host()
        return self._host

    def get_host(self):
        """Return host to controller.

        :return: Host to controller.
        """
        if self.get_connection_type() == 'ssh':
            return self.device.get_configurations("PROXY_PC", "LINUX")['command_params']['host']
        else:
            ip_addr_cmd = self.device.get_cmd(cmd_name='ip_addr')
            result = ip_addr_cmd()
            return result['br0']['IPV4'][0]['IP']
